import json, subprocess, pathlib

def credentials(path):
    r = subprocess.run(["c2patool", str(path)], capture_output=True, text=True)
    if r.returncode != 0 or not r.stdout.strip():
        return None
    return json.loads(r.stdout)

folder = pathlib.Path("reshared")            # assets downloaded after sharing
files = sorted(folder.glob("*.jpg"))
kept = [f.name for f in files if credentials(f)]
print(f"C2PA credentials survived on {len(kept)} of {len(files)} re-shared files")
